<script module lang="ts">
/**
 * A stored rich-text document drawn through the vocabulary (`design/components/rich-text-content.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rich-text-content.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, setContext, type Snippet } from 'svelte'

import {
  RICH_TEXT_STOP,
  agentMember,
  agentPress,
  bindSnippet,
  enterToolbar,
  followSelectionBar,
  holdToolbarEscape,
  joinSlot,
  mapRichTextSelection,
  placeSelectionBar,
  richTextAnnotations,
  richTextDrawing,
  richTextKeyedAnnotation,
  richTextPressedAnnotation,
  richTextSelectionBox,
  serializeRichText,
  slotDraws,
  syncToolbarStop,
  toolbarFocusIn,
  toolbarFocusOut,
  toolbarKeydown,
  toolbarPress,
  toolbarStop,
  watchEffect,
  type RichTextDocument,
  type RichTextEntity,
  type RichTextRange,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/structure/rich-text-content.module.css'
import selectionBar from '@polymorph/recipes/controls/selection-bar.module.css'
import RichTextContentBlocks from './RichTextContentBlocks.svelte'

export type RichTextContentSize = NonNullable<RichTextContentProps['size']>

export interface RichTextContentSelection {
  range: RichTextRange
  text: string
}

export interface RichTextContentMessages {
  selectionBar?: string
  selectionBarReady?: string
}

export interface RichTextContentProps {
  /**
   * The drawn annotation that is active, such as the thread the app shows.
   */
  activeAnnotation?: string
  /**
   * The annotations drawn. Default: every one the document holds.
   */
  annotations?: string[]
  /**
   * The app's rendering of an entity: a Link to the person's page, a HoverCard with their card.
   * `undefined` draws the entity token, so an app can draw one kind itself and leave the others
   * as tokens.
   */
  entity?: Snippet<[RichTextEntity]>
  /**
   * The page level the document's level 1 heading is drawn at. Each deeper level adds one, up to
   * 4. Default 2, one level under the page's title.
   */
  headingLevel?: 2 | 3 | 4
  /**
   * The selection bar's words, in the app's language.
   */
  messages?: RichTextContentMessages
  /**
   * A press on a drawn annotation. Without it the highlights take no press and no focus.
   */
  onAnnotationSelect?: (id: string) => void
  /**
   * The app's router, handed to every Link the document draws (`link.md`).
   */
  onNavigate?: (href: string) => void
  /**
   * The app's controls for the reader's selected text, in a bar at the selection.
   */
  selectionActions?: Snippet<[RichTextContentSelection]>
  /**
   * The body text step (Text's `sm` or `md`), which does not change the heading scale.
   */
  size?: 'sm' | 'md'
  /**
   * The stored document. Any JSON is read as far as it can be; what is not a document draws
   * nothing.
   */
  value: RichTextDocument
}
</script>

<script lang="ts">
let {
  activeAnnotation,
  annotations,
  entity,
  headingLevel,
  messages,
  onAnnotationSelect,
  onNavigate,
  selectionActions,
  size = 'md',
  value,
}: RichTextContentProps = $props()
const joined = joinSlot(undefined, () => ({ size: size }))
const listening = {
  get annotationSelect() {
    return onAnnotationSelect !== undefined
  },
  get navigate() {
    return onNavigate !== undefined
  },
}
const slots = {
  get entity() {
    return entity
  },
  get selectionActions() {
    return selectionActions
  },
}
let selected = $state({
  now: null as { range: RichTextRange; text: string; key: string } | null,
  last: null as { range: RichTextRange; text: string; key: string } | null,
})
let selecting = $state(false)
let dismissed = $state(null as string | null)
let barFocus = $state(false)
let said = $state({ text: '', at: 0 })
let barHeard = $state(false)
let bar = $state<HTMLElement | null>(null)
let root = $state<HTMLElement | null>(null)
let status = $state<HTMLElement | null>(null)
const held = $derived({
  range: null as Range | null,
  cameFrom: null as HTMLElement | null,
  restoring: false,
})
const say = $derived({
  selectionBar: messages?.selectionBar ?? 'Selection',
  selectionBarReady:
    messages?.selectionBarReady ?? 'Controls for the selection are available: Alt+F10',
})
const pressable = $derived(listening.annotationSelect)
const routes = $derived(listening.navigate)
const navigate = $derived((href: string) => onNavigate?.(href))
const entityNode = $derived((drawn: RichTextEntity) => bindSnippet(entity, drawn))
const mapped = $derived(!!slots.selectionActions)
const appDraws = $derived((drawn: RichTextEntity) => slotDraws(entity, drawn))
const drawing = $derived(
  richTextDrawing(value, {
    headingLevel,
    annotations,
    activeAnnotation,
    pressable,
    positions: mapped,
    appDraws,
  }),
)
const drawn = $derived((id: string) => annotations === undefined || annotations.includes(id))
const offering = $derived(mapped && !drawing.empty)
const docKey = $derived(offering ? serializeRichText(drawing.value) : '')
const shown = $derived(selected.now ?? (barFocus ? selected.last : null))
const barOpen = $derived(offering && shown !== null && !selecting && dismissed !== shown.key)
const content = $derived(selected.now ?? selected.last)
const announce = $derived((words: string) => {
  said = { text: words, at: said.at + 1 }
})
const outside = $derived(
  (node: Node): Element | null =>
    [bar, status].find((part) => part?.contains(node) === true) ?? null,
)
const updateSelection = $derived(() => {
  const found = root ? mapRichTextSelection(root, outside, drawing.value) : null
  if (found !== null) held.range = found.dom
  // A dismissal holds for one selection: once it collapses, the next one brings the bar back.
  else dismissed = null
  if (found === null) {
    if (selected.now !== null) selected = { now: null, last: selected.last }
    return
  }
  if (selected.now?.key === found.key && selected.now.text === found.text) return
  const mapping = { range: found.range, text: found.text, key: found.key }
  selected = { now: mapping, last: mapping }
})
const followSelection = $derived((element: HTMLElement) => {
  const page = element.ownerDocument
  const update = () => updateSelection()
  page.addEventListener('selectionchange', update)
  return () => page.removeEventListener('selectionchange', update)
})
const releaseSelecting = $derived((element: HTMLElement) => {
  const view = element.ownerDocument.defaultView
  const release = () => {
    selecting = false
  }
  view?.addEventListener('pointerup', release, true)
  view?.addEventListener('pointercancel', release, true)
  return () => {
    view?.removeEventListener('pointerup', release, true)
    view?.removeEventListener('pointercancel', release, true)
  }
})
const holdKeys = $derived((element: HTMLElement) => {
  const view = element.ownerDocument.defaultView
  const keys = (event: KeyboardEvent) => {
    const target = event.target
    if (event.isComposing || !(target instanceof Node)) return
    if (bar?.contains(target) === true) return
    const page = element.ownerDocument
    if (target !== page.body && target !== page.documentElement && !element.contains(target)) return
    if (event.key === 'Escape') {
      event.preventDefault()
      if (shown !== null) dismissed = shown.key
    } else if (event.key === 'F10' && event.altKey) {
      event.preventDefault()
      enterToolbar(bar, barStops)
    }
  }
  view?.addEventListener('keydown', keys, true)
  return () => view?.removeEventListener('keydown', keys, true)
})
const restoreSelection = $derived(() => {
  const range = held.range
  const selection = root?.ownerDocument.getSelection()
  if (range === null || selection === null || selection === undefined || !selection.isCollapsed)
    return
  selection.removeAllRanges()
  selection.addRange(range)
})
const leaveBar = $derived(() => {
  if (shown !== null) dismissed = shown.key
  held.restoring = true
  restoreSelection()
})
const giveFocusBack = $derived(() => {
  const to = held.cameFrom
  held.cameFrom = null
  const active = bar?.ownerDocument.activeElement
  if (to !== null && to.isConnected && bar?.contains(to) !== true) to.focus({ preventScroll: true })
  else if (active instanceof HTMLElement && bar?.contains(active) === true) active.blur()
  if (held.restoring) restoreSelection()
  held.restoring = false
})
const barLeave = $derived((event: FocusEvent) => {
  const to = event.relatedTarget
  if (to instanceof Node && (event.currentTarget as HTMLElement).contains(to)) return
  barFocus = false
  // A leaving bar is inert, and a browser that moves focus off it does so here.
  if (bar?.inert === true) giveFocusBack()
})
const cameFrom = $derived((event: FocusEvent) => {
  const from = event.relatedTarget
  if (from instanceof HTMLElement && bar?.contains(from) === true) return
  held.cameFrom = from instanceof HTMLElement ? from : null
})
const documentChanged = $derived(() => {
  selected = { now: null, last: null }
  held.range = null
  const selection = root?.ownerDocument.getSelection()
  if (root === null || root === undefined || selection === null || selection === undefined) return
  if (selection.rangeCount === 0 || selection.isCollapsed) return
  const range = selection.getRangeAt(0)
  if (root.contains(range.startContainer) || root.contains(range.endContainer))
    selection.collapseToEnd()
})
const measure = $derived(() => {
  const selection = root?.ownerDocument.getSelection()
  if (root && selection && selection.rangeCount > 0) {
    const range = selection.getRangeAt(0)
    if (!range.collapsed && root.contains(range.commonAncestorContainer))
      return richTextSelectionBox(range)
  }
  return held.range === null ? null : richTextSelectionBox(held.range)
})
const placeBar = $derived(() => placeSelectionBar(bar, measure()))
const barStops = $derived(toolbarStop())
const holdEscapeIn = $derived((element: HTMLElement) => {
  const view = element.ownerDocument.defaultView
  return view === null ? () => {} : holdToolbarEscape(view, () => bar)
})
const pressed = $derived((event: MouseEvent) => {
  const id = richTextPressedAnnotation(
    event.currentTarget as Element,
    event.target,
    event.detail,
    bar,
  )
  if (id !== null) onAnnotationSelect?.(id)
})
const keyed = $derived((event: KeyboardEvent, phase: 'down' | 'up') => {
  const id = richTextKeyedAnnotation(event, phase)
  if (id !== null) onAnnotationSelect?.(id)
})
const pressDown = $derived((event: PointerEvent) => {
  if (!(event.target instanceof Node) || bar?.contains(event.target) !== true) selecting = true
})
const barPresent = usePresence(
  () => barOpen,
  () => bar,
)
setContext('polymorph:RichTextContent', {
  get size() {
    return size
  },
  get pressable() {
    return pressable
  },
  get routes() {
    return routes
  },
  get navigate() {
    return navigate
  },
  get entityNode() {
    return entityNode
  },
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = offering && root ? followSelection(root) : () => {}
  release1 = () => {
    ran()
  }
}
watchEffect(effect1, { watch: () => offering })
onDestroy(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = selecting && root ? releaseSelecting(root) : () => {}
  release2 = () => {
    ran()
  }
}
watchEffect(effect2, { watch: () => selecting })
onDestroy(() => release2?.())
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = barOpen && root ? holdKeys(root) : () => {}
  release3 = () => {
    ran()
  }
}
watchEffect(effect3, { watch: () => barOpen })
onDestroy(() => release3?.())
const effect4 = () => {
  documentChanged()
}
watchEffect(effect4, { watch: () => docKey, mount: false })
const effect5 = () => {
  !barOpen && bar?.contains(bar.ownerDocument.activeElement) === true && giveFocusBack()
}
watchEffect(effect5, { watch: () => barOpen, mount: false })
const effect6 = () => {
  barOpen && !barHeard && ((barHeard = true), announce(say.selectionBarReady))
}
watchEffect(effect6, { watch: () => barOpen })
let release7: (() => void) | undefined
const effect7 = () => {
  release7?.()
  const run = () => {
    syncToolbarStop(bar, barStops)
  }
  const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
  for (const element of [bar])
    if (element)
      mutation?.observe(element, {
        childList: true,
        characterData: true,
        subtree: true,
        attributeFilter: ['disabled', 'aria-disabled', 'hidden', 'inert'],
      })
  release7 = () => {
    mutation?.disconnect()
  }
  run()
}
watchEffect(effect7, { watch: () => barPresent.current })
onDestroy(() => release7?.())
let release8: (() => void) | undefined
const effect8 = () => {
  release8?.()
  const ran = barPresent.current && bar ? holdEscapeIn(bar) : () => {}
  release8 = () => {
    ran()
  }
}
watchEffect(effect8, { watch: () => barPresent.current })
onDestroy(() => release8?.())
const effect9 = () => {
  barOpen && placeBar()
}
watchEffect(effect9, { watch: () => [barOpen, selected] })
let release10: (() => void) | undefined
const effect10 = () => {
  release10?.()
  const ran = barOpen && bar ? followSelectionBar(bar, placeBar) : () => {}
  release10 = () => {
    ran()
  }
}
watchEffect(effect10, { watch: () => barOpen })
onDestroy(() => release10?.())
let release11: (() => void) | undefined
const effect11 = () => {
  release11?.()
  const ran = !listening.annotationSelect
    ? () => {}
    : agentMember({
        member: 'RichTextContent',
        element: () => root,
        state: () => ({
          annotations: richTextAnnotations(drawing.value)
            .filter((annotation) => drawn(annotation.id))
            .map((annotation) => ({
              id: annotation.id,
              label: annotation.text,
              ...(drawing.stops.includes(annotation.id) ? {} : { disabled: true }),
            })),
          active: richTextAnnotations(drawing.value).some(
            (annotation) => drawn(annotation.id) && annotation.id === activeAnnotation,
          )
            ? (activeAnnotation ?? null)
            : null,
        }),
        actions: {
          select: {
            argument: 'id',
            run: (value) =>
              (() => {
                const stop = Array.from(root?.querySelectorAll(RICH_TEXT_STOP) ?? []).find(
                  (element) => element.getAttribute('data-annotation-id') === value,
                )
                if (stop === undefined)
                  throw new Error('That annotation has no highlight to press.')
                agentPress(stop)
              })(),
          },
        },
      })
  release11 = () => {
    ran()
  }
}
watchEffect(effect11)
onDestroy(() => release11?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.root}
    data-size={size}
    data-empty={(drawing.empty) ? '' : undefined}
    data-member="rich-text-content"
    onclick={(event) => { if (pressable) pressed(event) }}
    onkeydown={(event) => { if (pressable) keyed(event, 'down') }}
    onkeyup={(event) => { if (pressable) keyed(event, 'up') }}
    onpointerdown={(event) => { if (offering) pressDown(event) }}
    >{#if !drawing.empty}<RichTextContentBlocks blocks={drawing.blocks} />{/if
    }{#if offering && barPresent.current
      }<div
        bind:this={bar}
        class={selectionBar.bar}
        role="toolbar"
        aria-label={say.selectionBar}
        data-state={(!barOpen) ? 'closed' : undefined}
        inert={(!barOpen) ? true : undefined}
        onkeydown={(event) => { toolbarKeydown(event.currentTarget as HTMLElement, event, barStops, leaveBar) }}
        onfocusin={(event) => { (toolbarFocusIn(event.currentTarget as HTMLElement, event, barStops), (barFocus = true)) }}
        onfocusout={(event) => { (toolbarFocusOut(event.currentTarget as HTMLElement, event, barStops), barLeave(event)) }}
        onmousedown={(event) => { toolbarPress(event.currentTarget as HTMLElement, event) }}
        ><div class={styles.actions} onfocusin={(event) => { cameFrom(event) }}
          >{#if content !== null
            }{@render selectionActions?.({ range: content.range, text: content.text })
          }{/if
        }</div
      ></div
    >{/if
    }{#if offering
      }<div bind:this={status} class={styles.status} role="status" aria-live="polite"
        >{#if said.text !== ''}{#key said.at}<span>{said.text}</span>{/key}{/if
      }</div
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
